<section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-4">Documento</th><th class="px-5 py-4">Nombres y apellidos</th><th class="px-5 py-4">Teléfono</th><th class="px-5 py-4">Correo</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($personas as $persona): ?><tr><td class="px-5 py-4"><?= htmlspecialchars($persona['numero_documento']) ?></td><td class="px-5 py-4 font-medium"><?= htmlspecialchars($persona['apellidos'] . ', ' . $persona['nombres']) ?></td><td class="px-5 py-4"><?= htmlspecialchars($persona['telefono'] ?: '—') ?></td><td class="px-5 py-4"><?= htmlspecialchars($persona['correo'] ?: '—') ?></td></tr><?php endforeach; ?><?php if (!$personas): ?><tr><td colspan="4" class="px-5 py-12 text-center text-slate-500">No hay registros activos.</td></tr><?php endif; ?></tbody></table></div></section>
